7: function hexToRgb(h) {
8:   h = h.replace('#','');
9:   if (h.length === 3) h = h.split('').map(c=>c+c).join('');
10:   return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)];
11: }
12: function rgbToHex(r,g,b) { return '#' + [r,g,b].map(v=>clamp(Math.round(v),0,255).toString(16).padStart(2,'0')).join(''); }
13: function shiftColor(hex, deg, satMul=1, lightMul=1) {
14:   let [r,g,b] = hexToRgb(hex).map(v=>v/255);
15:   const max = Math.max(r,g,b), min = Math.min(r,g,b);
16:   let h=0, s=0, l=(max+min)/2;
17:   if (max !== min) {
18:     const d = max-min;
19:     s = l > .5 ? d/(2-max-min) : d/(max+min);
20:     h = max===r ? ((g-b)/d+(g<b?6:0)) : max===g ? ((b-r)/d+2) : ((r-g)/d+4);
21:     h *= 60;
22:   }
23:   h = (h + deg + 360) % 360; s = clamp(s*satMul,0,1); l = clamp(l*lightMul,0,1);
24:   const c = (1-Math.abs(2*l-1))*s, x = c*(1-Math.abs((h/60)%2-1)), m = l-c/2;
25:   let rr=0,gg=0,bb=0;
26:   if (h<60){rr=c;gg=x;} else if(h<120){rr=x;gg=c;} else if(h<180){gg=c;bb=x;}
27:   else if(h<240){gg=x;bb=c;} else if(h<300){rr=x;bb=c;} else {rr=c;bb=x;}
28:   return rgbToHex((rr+m)*255,(gg+m)*255,(bb+m)*255);
29: }
