116: function makeCreatureCanvas(sp, opts={}) {
117:   const S = 160;
118:   const c = document.createElement('canvas'); c.width=S; c.height=S;
119:   const x = c.getContext('2d'); x.imageSmoothingEnabled=false;
120:   const shiny = !!opts.shiny;
121:   let [base,dark,light,accent,extra] = sp.cols;
122:   if (shiny) {
123:     base = shiftColor(base, 55, 1.15, 1.05);
124:     dark = shiftColor(dark, 55, 1.1, .9);
125:     light = shiftColor(light, 50, 1.1, 1.02);
126:     accent = shiftColor(accent, 125, 1.2, 1.05);
127:     extra = shiftColor(extra, 125, 1.1, 1.02);
128:   }
129:   const C = {base,dark,light,accent,extra,shiny};
130:   x.save();
131:   const scale = sp.scale || 1;
132:   // Render at 2x with a small safe margin for the outline pass.
133:   x.translate(S/2, S/2); x.scale(2*scale, 2*scale); x.translate(-36, -36);
134: 
135:   const shape = sp.shape || 'quad';
136:   const f = new Set(sp.features||[]);
137: 
138:   // --- shared feature helpers ---
139:   const wings = (cx,cy,span,drop,wingCol,edgeCol) => {
140:     PX.tri(x,cx,cy,cx-span,cy-drop,cx-span*.35,cy+drop*.9,edgeCol);
141:     PX.tri(x,cx,cy,cx-span*.92,cy-drop*.85,cx-span*.3,cy+drop*.55,wingCol);
142:     PX.tri(x,cx,cy,cx+span,cy-drop,cx+span*.35,cy+drop*.9,edgeCol);
143:     PX.tri(x,cx,cy,cx+span*.92,cy-drop*.85,cx+span*.3,cy+drop*.55,wingCol);
144:   };
145:   const horns = (cx,cy,spread,len,col=accent) => {
146:     PX.tri(x,cx-spread,cy,cx-spread*.5,cy-len,cx-spread*.15,cy,col);
147:     PX.tri(x,cx+spread,cy,cx+spread*.5,cy-len,cx+spread*.15,cy,col);
148:   };
149:   const flame = (cx,cy,size,col=accent,hi=extra) => {
150:     PX.ell(x,cx,cy+size*.3,size*.55,size*.5,col);
151:     PX.tri(x,cx-size*.55,cy+size*.2,cx,cy-size*.9,cx+size*.55,cy+size*.2,col);
152:     PX.tri(x,cx-size*.3,cy+size*.1,cx,cy-size*.5,cx+size*.25,cy+size*.1,hi);
153:     PX.ell(x,cx,cy+size*.32,size*.34,size*.26,hi);
154:   };
155:   const leaf = (cx,cy,w,h,rot=0,col=accent,vein=dark) => {
156:     // pixel leaf: pointed oval
157:     PX.ell(x,cx,cy,w,h,col);
158:     PX.tri(x,cx-w,cy,cx,cy-h*1.4,cx+w,cy,col);
159:     PX.line(x,cx,cy+h*.6,cx,cy-h*.8,vein,1);
160:   };
161:   const crystal = (cx,cy,w,h,col=accent,hi=extra) => {
162:     PX.tri(x,cx,cy-h,cx-w,cy+h*.15,cx+w,cy+h*.15,col);
163:     PX.tri(x,cx-w*.3,cy-h*.65,cx-w*.1,cy+h*.15,cx+w*.2,cy+h*.15,hi);
164:   };
165:   const eyeSet = (cx,cy,gap,rx=3,ry=4) => { eye(x,cx-gap,cy,rx,ry); eye(x,cx+gap,cy,rx,ry); };
166:   const spark = (sx,sy,s,col) => {
167:     PX.rect(x,sx-s,sy,2*s+1,1,col); PX.rect(x,sx,sy-s,1,2*s+1,col);
168:     PX.rect(x,sx,sy,1,1,'#ffffff');
169:   };
170:   const bubble = (sx,sy,r,col) => {
171:     PX.ell(x,sx,sy,r,r,spriteAlpha(col,.30));
172:     PX.ell(x,sx-r*.3,sy-r*.3,Math.max(1,r*.4),Math.max(1,r*.4),spriteAlpha('#ffffff',.75));
173:   };
174:   const typeFlair = type => {
175:     if (type === 'Fire') {
176:       PX.rect(x,10,52,2,2,spriteAlpha(accent,.85)); PX.rect(x,7,47,1,3,spriteAlpha(extra,.8));
177:       PX.rect(x,60,11,2,2,spriteAlpha(accent,.8)); PX.rect(x,64,16,1,2,spriteAlpha(extra,.7));
178:     } else if (type === 'Water') {
179:       bubble(10,26,3,accent); bubble(63,52,2.2,accent); bubble(58,8,1.6,extra);
180:     } else if (type === 'Grass') {
181:       PX.ell(x,9,24,4,2,shiftColor(accent,0,1,.9)); PX.tri(x,6,24,11,17,13,25,accent);
182:       PX.ell(x,61,52,3.5,2,accent); PX.tri(x,58,52,63,45,65,53,shiftColor(accent,12,1,.95));
183:     } else if (type === 'Electric') {
184:       spark(9,22,3,accent); spark(62,14,2,extra); spark(57,55,1.5,accent);
185:     } else if (type === 'Ghost') {
186:       PX.ell(x,11,50,4,4,spriteAlpha(accent,.32)); PX.ell(x,63,42,3,3,spriteAlpha(accent,.26));
187:       PX.ell(x,58,10,2.5,2.5,spriteAlpha(extra,.30));
188:     } else if (type === 'Ice') {
189:       spark(10,18,3,light); spark(63,46,2.4,extra); PX.rect(x,56,9,2,1,spriteAlpha(light,.8));
190:     } else if (type === 'Fairy') {
191:       spark(11,20,3,extra); spark(62,50,2.4,accent); PX.rect(x,58,9,1,1,'#ffffff');
