197:       PX.rect(x,57,56,2,1,spriteAlpha(accent,.5));
198:     } else if (type === 'Dark' || type === 'Poison') {
199:       PX.ell(x,10,54,4,3,spriteAlpha(dark,.4)); PX.ell(x,62,50,3,2.5,spriteAlpha(accent,.30));
200:     } else if (type === 'Ground' || type === 'Rock') {
201:       PX.rect(x,12,62,2,1,spriteAlpha(dark,.5)); PX.rect(x,56,61,3,1,spriteAlpha(dark,.4));
202:       PX.rect(x,7,57,1,1,spriteAlpha(light,.5));
203:     } else if (type === 'Steel') {
204:       spark(11,30,2.2,light); spark(62,18,1.8,extra);
205:     } else if (type === 'Bug') {
206:       PX.rect(x,10,36,1,1,spriteAlpha(accent,.9)); PX.rect(x,61,40,1,1,spriteAlpha(extra,.8));
207:     } else if (type === 'Flying') {
