407:   function buildStaticLayer(map) {
408:     if (!map) return null;
409:     const cached = layerCache.get(map.id);
410:     if (cached) return cached;
411:     const PAD = 48;
412:     const c = document.createElement('canvas');
413:     c.width = map.width * T + PAD * 2; c.height = map.height * T + PAD * 2;
414:     const ctx = c.getContext('2d');
415:     ctx.imageSmoothingEnabled = false;
416:     ctx.translate(PAD, PAD);
417:     const seed = (hashStr(map.id) % 99991) | 0;
418:     for (let y = 0; y < map.height; y++) for (let x = 0; x < map.width; x++) {
419:       drawTile(ctx, map.tiles[y][x], x, y, seed + x * 131 + y * 977);
420:     }
421:     transitions(ctx, map);
422:     // bake soft ambient occlusion at map borders
423:     const edge = ctx.createLinearGradient(0, 0, 0, 64);
424:     edge.addColorStop(0, 'rgba(4,6,16,.35)'); edge.addColorStop(1, 'rgba(4,6,16,0)');
425:     ctx.fillStyle = edge; ctx.fillRect(0, 0, map.width * T, 64);
426:     // props sorted so taller / lower objects paint last
427:     const props = map.objects.slice().sort((a, b) => (a.y + (a.height || 1)) - (b.y + (b.height || 1)));
428:     for (const o of props) Art.drawProp(ctx, o, map);
429:     c._pad = PAD;
430:     layerCache.set(map.id, c);
431:     return c;
432:   }
