476: /* Add a crisp outer outline, top-left rim light and subtle inner shading. */
477: function finishCreatureSprite(canvas, C) {
478:   const w = canvas.width, h = canvas.height;
479:   const ctx = canvas.getContext('2d');
480:   let img;
481:   try { img = ctx.getImageData(0, 0, w, h); } catch (error) { return; }
482:   const src = img.data;
483:   const out = new Uint8ClampedArray(src);
484:   const [or, og, ob] = hexToRgb(shiftColor(C.dark, 0, 1, .62));
485:   const [lr, lg, lb] = hexToRgb(C.light);
