512: const CREATURE_CACHE = new Map();
513: function creatureCanvas(id, shiny = false, key = '') {
514:   const k = id + '|' + (shiny?'s':'n') + '|' + key;
515:   if (CREATURE_CACHE.has(k)) return CREATURE_CACHE.get(k);
516:   const sp = SPECIES[id];
517:   if (!sp) return null;
518:   const c = makeCreatureCanvas(sp, { shiny });
519:   CREATURE_CACHE.set(k, c);
520:   return c;
521: }
522: function drawCreature(ctx, id, x, y, size, opts = {}) {
523:   const sp = SPECIES[id];
524:   if (!sp) return;
525:   const c = creatureCanvas(id, opts.shiny || false, opts.cacheKey || '');
526:   if (!c) return;
527:   ctx.save();
528:   ctx.imageSmoothingEnabled = false;
529:   if (opts.flip) { ctx.translate(x + size/2, 0); ctx.scale(-1,1); ctx.translate(-(x + size/2),0); }
530:   if (opts.alpha != null) ctx.globalAlpha = opts.alpha;
531:   ctx.drawImage(c, x, y, size, size);
532:   ctx.restore();
533: }

