308:   function drawTile(ctx, tile, x, y, seed) {
309:     const tx = x * T, ty = y * T;
310:     switch (tile) {
311:       case 'grass': grassTile(ctx, tx, ty, seed); break;
312:       case 'grass_flower': grassTile(ctx, tx, ty, seed, true); break;
313:       case 'tall_grass': tallGrassTile(ctx, tx, ty, seed); break;
314:       case 'path': case 'path2': pathTile(ctx, tx, ty, seed); break;
315:       case 'sand': sandTile(ctx, tx, ty, seed); break;
316:       case 'sand_pebble': sandTile(ctx, tx, ty, seed, true); break;
317:       case 'sand_path': pathTile(ctx, tx, ty, seed, 'sand'); break;
318:       case 'rock': rockTile(ctx, tx, ty, seed); break;
319:       case 'snow': snowTile(ctx, tx, ty, seed); break;
320:       case 'snow_rock': snowTile(ctx, tx, ty, seed, true); break;
321:       case 'snow_path': snowTile(ctx, tx, ty, seed); pathTile(ctx, tx, ty, seed + 2, 'snow'); break;
322:       case 'cave_floor': caveFloorTile(ctx, tx, ty, seed); break;
323:       case 'cave_path': cavePathTile(ctx, tx, ty, seed); break;
324:       case 'water': waterTile(ctx, tx, ty, seed); break;
325:       case 'pier': pierTile(ctx, tx, ty, seed); break;
326:       case 'floor': floorTile(ctx, tx, ty, seed); break;
327:       case 'wall': wallTile(ctx, tx, ty, seed); break;
328:       case 'building_wall': brickTile(ctx, tx, ty, seed); break;
329:       case 'doorstep': doorstepTile(ctx, tx, ty, seed); break;
330:       case 'counter': counterTile(ctx, tx, ty, seed); break;
331:       case 'ancient_floor': ancientTile(ctx, tx, ty, seed); break;
332:       default:
333:         if (String(tile).endsWith('_roof')) roofTile(ctx, tx, ty, seed);
334:         else if (String(tile).includes('wall')) brickTile(ctx, tx, ty, seed);
335:         else grassTile(ctx, tx, ty, seed);
336:     }
337:   }
