339:   /* ------------------------------------------------ transitions */
340:   function tileCat(tile) {
341:     if (!tile) return 'void';
342:     if (tile === 'water') return 'water';
343:     if (tile === 'pier') return 'pier';
344:     if (tile === 'path' || tile === 'path2' || tile === 'sand_path' || tile === 'snow_path' || tile === 'doorstep' || tile === 'cave_path') return 'path';
345:     if (tile === 'sand' || tile === 'sand_pebble') return 'sand';
346:     if (tile === 'snow' || tile === 'snow_rock') return 'snow';
347:     if (tile === 'rock') return 'rock';
348:     if (tile === 'cave_floor') return 'cave';
349:     if (tile === 'floor' || tile === 'counter') return 'floor';
350:     if (tile === 'wall' || tile.includes('wall') || tile.includes('roof')) return 'wall';
351:     if (tile === 'ancient_floor') return 'ancient';
352:     if (tile === 'tall_grass') return 'tall';
353:     return 'grass';
354:   }
355: 
356:   function fringeColors(tile) {
357:     const c = tileCat(tile);
358:     if (c === 'sand') return { tuft: '#c3a05d', hi: '#eed79b' };
359:     if (c === 'snow') return { tuft: '#c3d9e6', hi: '#ffffff' };
360:     if (c === 'rock') return { tuft: '#4b795a', hi: '#7f8da1' };
361:     if (c === 'cave') return { tuft: '#343b58', hi: '#454e70' };
362:     if (c === 'tall') return { tuft: '#1d5a38', hi: '#2f8a52' };
363:     if (c === 'ancient') return { tuft: '#45434f', hi: '#716d7c' };
364:     return { tuft: '#174a33', hi: '#469b6b' };
365:   }
366: 
367:   function transitions(ctx, map) {
368:     const { width, height, tiles } = map;
369:     const at = (x, y) => (x < 0 || y < 0 || x >= width || y >= height) ? null : tiles[y][x];
370:     for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
371:       const tile = tiles[y][x], cat = tileCat(tile), tx = x * T, ty = y * T;
372:       const nbs = [[x, y - 1, 'n'], [x + 1, y, 'e'], [x, y + 1, 's'], [x - 1, y, 'w']];
373:       for (const [nx, ny, side] of nbs) {
374:         const n = at(nx, ny); if (n === null) continue;
375:         const ncat = tileCat(n);
376:         if (ncat === cat) continue;
377:         // Keep path-on-path variants seamless.
378:         if (cat === 'path' && ncat === 'path') continue;
379:         if (cat === 'water' && ncat !== 'water') {
380:           const foam = 'rgba(160,235,255,.5)';
381:           if (side === 'n') PX.rect(ctx, tx, ty, T, 2, foam);
382:           if (side === 's') PX.rect(ctx, tx, ty + T - 2, T, 2, foam);
383:           if (side === 'w') PX.rect(ctx, tx, ty, 2, T, foam);
384:           if (side === 'e') PX.rect(ctx, tx + T - 2, ty, 2, T, foam);
385:           continue;
386:         }
387:         if (cat === 'path' && (ncat === 'grass' || ncat === 'tall' || ncat === 'sand' || ncat === 'snow' || ncat === 'rock')) {
388:           const c = fringeColors(n);
389:           const r = seeded(x, y, ncat.length * 7);
390:           for (let i = 0; i < 4; i++) {
391:             const off = Math.floor(r() * 28);
392:             if (side === 'n') { PX.rect(ctx, tx + off, ty, 2, 2, c.tuft); PX.rect(ctx, tx + off + 1, ty + 2, 1, 2, c.hi); }
393:             if (side === 's') { PX.rect(ctx, tx + off, ty + T - 2, 2, 2, c.tuft); PX.rect(ctx, tx + off + 1, ty + T - 4, 1, 2, c.hi); }
