522: function drawCreature(ctx, id, x, y, size, opts = {}) {
523:   const sp = SPECIES[id];
524:   if (!sp) return;
525:   const c = creatureCanvas(id, opts.shiny || false, opts.cacheKey || '');
526:   if (!c) return;
527:   ctx.save();
528:   ctx.imageSmoothingEnabled = false;
529:   if (opts.flip) { ctx.translate(x + size/2, 0); ctx.scale(-1,1); ctx.translate(-(x + size/2),0); }
530:   if (opts.alpha != null) ctx.globalAlpha = opts.alpha;
531:   ctx.drawImage(c, x, y, size, size);
532:   ctx.restore();
533: }

