1: /* ============================================================
2:    POKÉMON ECLIPSE — game bootstrap, persistence, and controls
3:    ============================================================ */
4: 'use strict';
5: 
6: const Game = {
7:   state: 'title',
8:   party: [],
9:   inventory: { potion: 3, poke_ball: 5 },
10:   player: { name: 'Aurelia', money: 3000 },
11:   flags: {},
12:   storage: [],
13:   started: false
14: };
15: 
16: globalThis.Game = Game;
17: 
18: const SAVE_KEY = 'pokemon_eclipse_aurelia_v1';
19: let titleActive = true;
20: let lastStep = 0;
21: let stepDelay = 0;
22: 
23: function starterEntries() {
24:   return [
25:     { label: 'Sobble', detail: 'Water / Ghost', sprite: 'sobble_a', value: 'sobble_a' },
26:     { label: 'Litten', detail: 'Fire / Ground', sprite: 'litten_a', value: 'litten_a' },
27:     { label: 'Treecko', detail: 'Grass / Fighting', sprite: 'treecko_a', value: 'treecko_a' }
28:   ];
29: }
30: 
31: function saveGame() {
32:   if (!Game.started) return false;
33:   const payload = {
34:     version: 1,
35:     party: Game.party,
36:     inventory: Game.inventory,
37:     player: Game.player,
38:     flags: Game.flags,
39:     storage: Game.storage,
40:     world: {
41:       mapId: World.state.mapId,
42:       x: World.state.x,
43:       y: World.state.y,
44:       facing: World.state.facing,
45:       defeated: World.state.defeated
46:     }
47:   };
48:   try { localStorage.setItem(SAVE_KEY, JSON.stringify(payload)); toast('Game saved.'); return true; }
49:   catch (error) { toast('Unable to save in this browser.'); return false; }
50: }
51: 
52: globalThis.saveGame = saveGame;
53: 
54: function readSave() {
55:   try {
56:     const raw = localStorage.getItem(SAVE_KEY);
57:     return raw ? JSON.parse(raw) : null;
58:   } catch (error) { return null; }
59: }
60: 
61: function applySave(save) {
62:   if (!save || !Array.isArray(save.party) || !save.party.length) return false;
63:   Game.party = save.party;
64:   // Accept the early prototype's `pokeball` key, but keep the canonical item ID.
65:   const savedInventory = Object.assign({}, save.inventory || {});
66:   if (savedInventory.pokeball != null && savedInventory.poke_ball == null) savedInventory.poke_ball = savedInventory.pokeball;
67:   delete savedInventory.pokeball;
68:   Game.inventory = Object.assign({ potion: 3, poke_ball: 5 }, savedInventory);
69:   Game.player = Object.assign({ name: 'Aurelia', money: 3000 }, save.player || {});
70:   Game.flags = Object.assign({}, save.flags || {});
71:   Game.storage = Array.isArray(save.storage) ? save.storage : (Array.isArray(save.pc) ? save.pc : []);
72:   Game.started = true;
73:   const w = save.world || {};
74:   World.state.defeated = Object.assign({}, w.defeated || {});
75:   World.state.flags = Game.flags;
76:   World.setMap(MAPS[w.mapId] ? w.mapId : 'emberfall', Number.isFinite(w.x) ? w.x : 14, Number.isFinite(w.y) ? w.y : 18);
77:   World.state.facing = w.facing || 'up';
78:   World.init(Game);
79:   return true;
80: }
81: 
82: async function chooseStarter() {
83:   const choice = await UI.menu('Choose your first partner', starterEntries(), {
84:     layout: 'starters',
85:     description: 'Every journey begins with trust. Select a Pokémon to travel with you.',
86:     footer: 'Arrow keys / WASD to choose · Z / Enter to confirm'
87:   });
88:   if (!choice) return false;
89:   Game.party = [Battle.createMember(choice, 5)];
90:   Game.inventory = { potion: 3, poke_ball: 5 };
91:   Game.player = { name: 'Aurelia', money: 3000 };
92:   Game.flags = { starter: choice, intro: true };
93:   Game.storage = [];
94:   Game.started = true;
95:   World.state.defeated = {};
96:   World.state.flags = Game.flags;
97:   World.setMap('emberfall', 14, 18);
98:   World.init(Game);
99:   saveGame();
100:   return true;
101: }
102: 
103: let titleStart = 0;
104: 
105: function titleCanvas() {
106:   titleStart = performance.now();
107:   drawTitleFrame(performance.now());
108: }
109: 
110: function drawTitleFrame(now) {
111:   const canvas = $('#game');
112:   const ctx = canvas.getContext('2d');
113:   ctx.imageSmoothingEnabled = false;
114:   const time = (now - (titleStart || now)) / 1000;
115:   if (Art.drawTitle) Art.drawTitle(ctx, canvas.width, canvas.height, time);
116:   else { ctx.fillStyle = '#090d20'; ctx.fillRect(0, 0, canvas.width, canvas.height); }
117: }
118: 
119: async function beginNewGame() {
120:   titleActive = false;
121:   UI.close();
122:   Game.state = 'starting';
123:   if (await chooseStarter()) {
124:     Game.state = 'overworld';
125:     await UI.say('Welcome to Aurelia. Professor Cedar is waiting in the village lab.', 'Aurelia');
126:     World.draw();
127:   } else {
128:     titleActive = true; Game.state = 'title'; showTitle();
129:   }
130: }
131: 
132: async function continueGame() {
133:   const save = readSave();
134:   if (!save) { toast('No save data found.'); return; }
135:   titleActive = false; UI.close();
136:   if (applySave(save)) { Game.state = 'overworld'; World.draw(); toast('Save data loaded.'); }
137:   else { titleActive = true; showTitle(); toast('That save file is invalid.'); }
138: }
139: 
140: function showTitle() {
141:   titleActive = true; Game.state = 'title'; titleCanvas();
142:   const hasSave = !!readSave();
143:   UI.menu('Pokémon Eclipse', [
144:     { label: 'New Game', value: 'new' },
145:     { label: 'Continue', value: 'continue', disabled: !hasSave },
146:     { label: 'How to Play', value: 'help' }
147:   ], { layout: 'splash', description: 'Aurelia Genesis', footer: 'A journey beyond the eclipse' }).then(async choice => {
148:     if (!titleActive) return;
149:     if (choice === 'new') await beginNewGame();
150:     else if (choice === 'continue') await continueGame();
151:     else if (choice === 'help') {
152:       await UI.say('Move with arrows or WASD. Face a person or object and press Z or Enter to interact. Press X or Escape for your Pokémon menu. Tall grass hides wild Pokémon.', 'Guide');
153:       showTitle();
154:     }
155:   });
156: }
157: 
158: async function partyMenu() {
159:   const labels = Game.party.map(mon => `${mon.name} Lv.${mon.level}  ${Math.max(0, mon.hp)}/${mon.maxHp} HP`);
160:   labels.push({ label: 'Save Game', value: 'save' }, { label: 'Close', value: 'close' });
161:   const result = await UI.menu('Trainer Menu', labels, { footer: 'Z / Enter select · X / Esc close' });
162:   if (result === 'save') saveGame();
163:   else if (result && result !== 'close') {
164:     const mon = Game.party.find(p => p.name === result.split(' Lv.')[0]);
165:     if (mon) await UI.say(`${mon.name} is ready for adventure!`, 'Party');
166:   }
167: }
168: 
169: function onPress(key) {
170:   if (key === 'm') {
171:     Sound.musicOn = !Sound.musicOn;
172:     if (Sound.musicOn) Sound.playTrack(Game.state === 'overworld' ? 'town' : 'title');
173:     else Sound.stopMusic();
174:     toast(Sound.musicOn ? 'Music on.' : 'Music muted.');
175:     return;
176:   }
177:   if (titleActive || UI.active || Battle.busy) return;
178:   if (key === 'z' || key === 'enter') { World.interact(); return; }
179:   if (key === 'x' || key === 'escape') { partyMenu(); return; }
180: }
181: 
182: function heldMovement(now) {
183:   if (titleActive || UI.active || Battle.busy || Game.state !== 'overworld') return;
184:   if (now - lastStep < 135) return;
185:   let dx = 0, dy = 0;
186:   if (Input.down('arrowup', 'w')) dy = -1;
187:   else if (Input.down('arrowdown', 's')) dy = 1;
188:   else if (Input.down('arrowleft', 'a')) dx = -1;
189:   else if (Input.down('arrowright', 'd')) dx = 1;
190:   if (dx || dy) { World.step(dx, dy); lastStep = now; }
191: }
192: 
193: function loop(now) {
194:   requestAnimationFrame(loop);
195:   const dt = Math.min(100, now - (loop._last || now)); loop._last = now;
196:   try {
197:     heldMovement(now);
198:     if (titleActive) drawTitleFrame(now);
199:     else { World.update(dt); World.draw(); }
200:   } catch (error) {
201:     console.error('Frame error:', error);
202:   }
203: }
204: 
205: function boot() {
206:   Input.onPress(onPress);
207:   Sound.playTrack('title');
208:   showTitle();
209:   requestAnimationFrame(loop);
210: }
211: 
212: document.addEventListener('DOMContentLoaded', boot, { once: true });

