491:       const i = (y * w + x) * 4;
492:       if (src[i + 3] < 10) {
493:         let edge = false;
494:         for (const [dx, dy] of neighbors) {
495:           if (isOpaque(x + dx, y + dy)) { edge = true; break; }
496:         }
497:         if (edge) {
498:           out[i] = or; out[i + 1] = og; out[i + 2] = ob; out[i + 3] = 232;
499:         }
